import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.D6RJXrbK.js";const u=JSON.parse('{"title":"Lab 3：mini-openfga v0.3：临时授权、子问题缓存、BatchCheck 与 Expand","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/lab-3-conditions-cache.md","filePath":"chapters/lab-3-conditions-cache.md","lastUpdated":1791513046000}'),i={name:"chapters/lab-3-conditions-cache.md"};function p(o,e,c,l,d,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="lab-3-mini-openfga-v0-3-临时授权、子问题缓存、batchcheck-与-expand" tabindex="-1">Lab 3：mini-openfga v0.3：临时授权、子问题缓存、BatchCheck 与 Expand <a class="header-anchor" href="#lab-3-mini-openfga-v0-3-临时授权、子问题缓存、batchcheck-与-expand" aria-label="Permalink to &quot;Lab 3：mini-openfga v0.3：临时授权、子问题缓存、BatchCheck 与 Expand&quot;">​</a></h1><blockquote><p>目标：用条件实现“合同到期自动失效”的授权；观察子问题缓存怎样让第二、三个文档的检查少读存储；体验 BatchCheck 的去重和 Expand 的单层展开；确认 Check 矩阵测试全部通过。 前置：第 14–17 章。对应代码：mini-openfga <strong>v0.3</strong>（本 Lab 的程序在 v1.0 的 <code>examples/lab3/main.go</code>，在 v0.3 上照抄即可运行）。</p></blockquote><h2 id="_1-本版改了什么" tabindex="-1">1. 本版改了什么 <a class="header-anchor" href="#_1-本版改了什么" aria-label="Permalink to &quot;1. 本版改了什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-openfga</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.3</span></span></code></pre></div><table tabindex="0"><thead><tr><th>新增</th><th>内容</th></tr></thead><tbody><tr><td><code>pkg/condition/</code></td><td>CEL 编译与求值、参数类型、ipaddress、<code>$expression</code>、JSON 规整（第 14 章）</td></tr><tr><td><code>pkg/cache/lru.go</code></td><td>泛型 LRU + TTL</td></tr><tr><td><code>pkg/check/cached_resolver.go</code>、<code>throttling_resolver.go</code>、<code>builder.go</code></td><td>resolver 链（第 15 章）</td></tr><tr><td><code>pkg/expand/</code></td><td>Expand（第 16 章）</td></tr><tr><td><code>pkg/server/batch_check.go</code></td><td>BatchCheck（第 17 章）</td></tr><tr><td><code>pkg/server/server.go</code></td><td><code>Config</code>、<code>WithCheckCache</code>、<code>WithDispatchThrottling</code>；Check 支持 context 与 consistency</td></tr></tbody></table><h2 id="_2-模型与数据" tabindex="-1">2. 模型与数据 <a class="header-anchor" href="#_2-模型与数据" aria-label="Permalink to &quot;2. 模型与数据&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type user</span></span>
<span class="line"><span>type folder</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define viewer: [user, user with non_expired]</span></span>
<span class="line"><span>type document</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define parent: [folder]</span></span>
<span class="line"><span>    define viewer: [user] or viewer from parent</span></span>
<span class="line"><span>condition non_expired(current_time: timestamp, expires_at: timestamp) {</span></span>
<span class="line"><span>  current_time &lt; expires_at</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>folder:specs</code> 下有三份文档 spec1..spec3；anne 是 specs 的 viewer；外包人员 contractor 也是 viewer，但带条件 <code>non_expired</code>，元组上写着 <code>expires_at = 2026-12-31</code>。</p><h2 id="_3-运行" tabindex="-1">3. 运行 <a class="header-anchor" href="#_3-运行" aria-label="Permalink to &quot;3. 运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./examples/lab3</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== 1. time-limited access</span></span>
<span class="line"><span>current_time=&quot;2026-06-01T00:00:00Z&quot; allowed=true</span></span>
<span class="line"><span>current_time=&quot;2027-01-01T00:00:00Z&quot; allowed=false</span></span>
<span class="line"><span>current_time=&quot;&quot;                     error: &#39;non_expired&#39; - tuple is missing context parameters &#39;[current_time]&#39;</span></span>
<span class="line"><span>== 2. the check cache</span></span>
<span class="line"><span>document:spec1#viewer@user:anne allowed=true queries=3 cache hits +0</span></span>
<span class="line"><span>document:spec2#viewer@user:anne allowed=true queries=2 cache hits +1</span></span>
<span class="line"><span>document:spec3#viewer@user:anne allowed=true queries=2 cache hits +1</span></span>
<span class="line"><span>again spec1:                        queries=0</span></span>
<span class="line"><span>spec1 with HIGHER_CONSISTENCY:       queries=3</span></span>
<span class="line"><span>== 3. batch check</span></span>
<span class="line"><span>anne-1        allowed=true</span></span>
<span class="line"><span>anne-1-again  allowed=true</span></span>
<span class="line"><span>contractor-2  allowed=true</span></span>
<span class="line"><span>bob-3         allowed=false</span></span>
<span class="line"><span>== 4. expand</span></span>
<span class="line"><span>{&quot;name&quot;:&quot;document:spec1#viewer&quot;,&quot;union&quot;:[{&quot;name&quot;:&quot;document:spec1#viewer&quot;},{&quot;name&quot;:&quot;document:spec1#viewer&quot;,&quot;tupleToUserset&quot;:{&quot;tupleset&quot;:&quot;document:spec1#parent&quot;,&quot;computed&quot;:[&quot;folder:specs#viewer&quot;]}}]}</span></span></code></pre></div><h3 id="_3-1-临时授权" tabindex="-1">3.1 临时授权 <a class="header-anchor" href="#_3-1-临时授权" aria-label="Permalink to &quot;3.1 临时授权&quot;">​</a></h3><p>合同期内为 true，过期后为 false，<strong>不需要任何人去删除元组</strong>。不传 <code>current_time</code> 时是一个错误，而不是 false：引擎不知道现在几点，就不做判断（第 14 章的“缺少参数”）。</p><p>在实际系统里，<code>current_time</code> 由调用方的服务端填写（不能让客户端自己报时间）。<code>expires_at</code> 写在元组上，调用方无法覆盖：即使请求里也带了一个 <code>expires_at</code>，求值时元组上的值优先。</p><h3 id="_3-2-子问题缓存" tabindex="-1">3.2 子问题缓存 <a class="header-anchor" href="#_3-2-子问题缓存" aria-label="Permalink to &quot;3.2 子问题缓存&quot;">​</a></h3><ul><li>spec1：缓存是空的，读了 3 次存储（文档自己的 viewer、文档的 parent、folder:specs 的 viewer）；</li><li>spec2：只读了 2 次。<code>folder:specs#viewer@user:anne</code> 这个子问题在检查 spec1 时已经被缓存，所以<strong>命中 1 次</strong>，省掉一次读取；</li><li>spec3：同上；</li><li>再查 spec1：整个问题本身就在缓存里，<strong>0 次读取</strong>；</li><li>带 <code>HIGHER_CONSISTENCY</code>：绕过缓存，又是 3 次读取。</li></ul><p>这就是第 15 章说的“环形链让每个子问题都经过缓存”的实际效果：同一个文件夹下的文档越多，省得越多。</p><h3 id="_3-3-batchcheck" tabindex="-1">3.3 BatchCheck <a class="header-anchor" href="#_3-3-batchcheck" aria-label="Permalink to &quot;3.3 BatchCheck&quot;">​</a></h3><p><code>anne-1</code> 和 <code>anne-1-again</code> 是同一个问题，只求值一次。<code>contractor-2</code> 带自己的 context。bob 什么关系都没有，false。四项共用一个请求。</p><h3 id="_3-4-expand" tabindex="-1">3.4 Expand <a class="header-anchor" href="#_3-4-expand" aria-label="Permalink to &quot;3.4 Expand&quot;">​</a></h3><p><code>document:spec1#viewer</code> 是一个 union，两个子节点：直接用户（这份文档没有直接的 viewer，所以是空的；mini 内部的 JSON 用了 <code>omitempty</code>，空列表被省略了，HTTP 接口会输出 OpenFGA 格式的 <code>{&quot;leaf&quot;:{&quot;users&quot;:{&quot;users&quot;:[]}}}</code>），以及指向 <code>folder:specs#viewer</code> 的 TTU 叶子。</p><h2 id="_4-矩阵测试" tabindex="-1">4. 矩阵测试 <a class="header-anchor" href="#_4-矩阵测试" aria-label="Permalink to &quot;4. 矩阵测试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/minifga</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> matrix</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check assertions: 939 passed, 0 failed, 0 skipped (100.0%); tests: 298/298 fully passed</span></span></code></pre></div><p>缓存和限流不改变任何答案：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./internal/matrix/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TestMatrixCheckWithCacheAndThrottling</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assertions</span></span></code></pre></div><h2 id="_5-动手改" tabindex="-1">5. 动手改 <a class="header-anchor" href="#_5-动手改" aria-label="Permalink to &quot;5. 动手改&quot;">​</a></h2><ol><li><strong>公司网络限制</strong>：给 folder 再加一种 <code>user with in_office</code>（第 14 章的 ipaddress 条件），让 anne 只有在 <code>10.0.0.0/8</code> 内才能看。分别用 <code>user_ip</code> = <code>10.1.2.3</code> 和 <code>192.168.0.1</code> 检查。</li><li><strong>缓存的代价</strong>：开着缓存，先查一次 spec1（anne 为 true），然后删除 <code>folder:specs#viewer@user:anne</code>，立刻再查。结果是什么？为什么？有哪两种办法让它立刻变成 false？（答案在第 23 章。）</li><li><strong>限流</strong>：用 <code>server.WithDispatchThrottling(1, 50*time.Millisecond)</code> 创建 Server，构造一个需要 5 次 dispatch 的检查，计时并观察 <code>ResolutionMetadata.DispatchThrottled</code>。</li></ol><h2 id="_6-本版小结" tabindex="-1">6. 本版小结 <a class="header-anchor" href="#_6-本版小结" aria-label="Permalink to &quot;6. 本版小结&quot;">​</a></h2><p>v0.3 补齐了 Check 的全部语义（条件），并在 resolver 链上加入了缓存和限流，同时提供了 Expand 和 BatchCheck。Check 的矩阵测试在这一版全部通过。代码量 5020 行（非测试）。</p><p>下一步（Part V）是另一个方向的问题：不再问“能不能”，而是问“能对哪些”“谁能”。</p>`,31)])])}const k=a(i,[["render",p]]);export{u as __pageData,k as default};
